mapper.select:
SELECT ${groupExpr} AS `label`, ROUND(SUM(electricity_kwh), 2) AS `electricityKwh`, ROUND(SUM(hvac_kwh), 2) AS `hvacKwh`, ROUND(SUM(water_m3), 2) AS `waterM3`, ROUND(SUM(carbon_kg), 2) AS `carbonKg`, ROUND(AVG(cop_avg), 3) AS `copAvg`, ROUND(AVG(air_temp_avg), 2) AS `airTempAvg`, SUM(anomaly_hours) AS `anomalyHours`, COUNT(*) AS `days` FROM agg_building_daily
stat_date >= #{startDate} AND stat_date <= #{endDate}
GROUP BY ${groupExpr} ORDER BY `label`

SELECT CASE WHEN stat_hour BETWEEN 10 AND 12 OR stat_hour BETWEEN 14 AND 17 THEN '尖峰' WHEN stat_hour IN (8, 9, 13, 18, 19) THEN '高峰' WHEN stat_hour IN (7, 20, 21, 22) THEN '平段' ELSE '低谷' END AS `name`, ROUND(SUM(electricity_kwh), 2) AS `electricityKwh`,
COUNT(*) SUM(anomaly_hours) + 0 AS `hourCount` FROM fact_energy_hourly agg_site_hourly agg_time_hourly
stat_year >= YEAR(#{startDate}) AND stat_year <= YEAR(#{endDate}) AND ts >= #{startDate} AND ts < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND building_id IN #{b}
stat_date >= #{startDate} AND stat_date <= #{endDate} AND site_id = #{siteId}
GROUP BY `name` ORDER BY FIELD(`name`, '尖峰', '高峰', '平段', '低谷')

SELECT stat_hour AS `hour`, ROUND(SUM(electricity_kwh), 2) AS `kwh` FROM fact_energy_hourly agg_site_hourly agg_time_hourly
stat_year >= YEAR(#{startDate}) AND stat_year <= YEAR(#{endDate}) AND ts >= #{startDate} AND ts < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND building_id IN #{b}
stat_date >= #{startDate} AND stat_date <= #{endDate} AND site_id = #{siteId}
GROUP BY stat_hour ORDER BY stat_hour

SELECT -- 负荷加权 COP = ΣE_hvac / Σ(E_hvac/COP)，与节能模拟口径一致 ROUND(SUM(CASE WHEN cop > 0 AND hvac_kwh > 0 THEN hvac_kwh / cop END) , 8) AS hvacOverCop, ROUND(SUM(CASE WHEN cop > 0 AND hvac_kwh > 0 THEN hvac_kwh END), 3) AS weightedHvacKwh, ROUND(AVG(cop), 3) AS copAvgSimple, ROUND(MAX(cop), 3) AS copMax, ROUND(MIN(cop), 3) AS copMin, ROUND(STDDEV_SAMP(cop), 3) AS copStd, ROUND(SUM(hvac_kwh), 1) AS coolingKwh, ROUND(SUM(hvac_electricity_kwh), 1) AS hvacElectricityKwh, ROUND(AVG(chw_supply_temp_c), 2) AS supplyTempAvg, ROUND(AVG(chw_return_temp_c), 2) AS returnTempAvg, ROUND(AVG(chw_return_temp_c - chw_supply_temp_c), 2) AS deltaTAvg, COUNT(cop) AS sampleHours FROM fact_energy_hourly
cop IS NOT NULL AND stat_year >= YEAR(#{startDate}) AND stat_year <= YEAR(#{endDate}) AND ts >= #{startDate} AND ts < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND building_id IN #{b}

SELECT
    SUM(evaluated_hours) AS evaluatedHours,
    SUM(anomaly_hours)   AS anomalyHours,
    SUM(quality_hours)   AS qualityHours
FROM agg_anomaly_daily

    stat_date >= #{startDate} AND stat_date <= #{endDate}
    AND site_id = #{siteId}

        AND building_id IN
        #{b}

SELECT COUNT(*) AS eventCount, ROUND(AVG(duration_hours), 1) AS avgDurationHours, MAX(duration_hours) AS maxDurationHours, SUM(duration_hours) AS totalAnomalyHours FROM fact_anomaly_event
start_ts >= #{startDate} AND start_ts < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND site_id = #{siteId}
AND building_id IN #{b}

SELECT anomaly_type AS `type`, COUNT(*) AS `count` FROM fact_anomaly_event
start_ts >= #{startDate} AND start_ts < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND site_id = #{siteId}
AND building_id IN #{b}
GROUP BY anomaly_type ORDER BY `count` DESC

SELECT e.building_id AS buildingId, e.site_id AS siteId, MAX(b.building_type_cn) AS buildingTypeCn, SUM(e.duration_hours) AS anomalyHours, ROUND(SUM(e.duration_hours) / 8760.0, 4) AS anomalyRate, ROUND(MAX(e.deviation_pct), 2) AS peakDeviationPct, (SELECT MAX(e2.anomaly_type) FROM fact_anomaly_event e2 WHERE e2.building_id = e.building_id LIMIT 1) AS dominantType FROM fact_anomaly_event e LEFT JOIN dim_building b ON b.building_id = e.building_id
e.start_ts >= #{startDate} AND e.start_ts < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND e.site_id = #{siteId}
GROUP BY e.building_id, e.site_id ORDER BY anomalyHours DESC LIMIT #{limit}

SELECT DATE_FORMAT(start_ts, '%Y-%m-%d') AS `date`, SUM(duration_hours) AS anomalyHours, COUNT(*) AS eventCount FROM fact_anomaly_event
start_ts >= #{startDate} AND start_ts < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND site_id = #{siteId}
GROUP BY `date` ORDER BY `date`

SELECT e.id, e.building_id AS buildingId, e.site_id AS siteId, MAX(b.building_type_cn) AS buildingTypeCn, DATE_FORMAT(e.start_ts, '%Y-%m-%d %H:%i') AS startTs, DATE_FORMAT(e.end_ts, '%Y-%m-%d %H:%i') AS endTs, e.duration_hours AS durationHours, e.anomaly_type AS anomalyType, e.severity, e.peak_value AS peakValue, e.baseline_value AS baselineValue, e.deviation_pct AS deviationPct, e.handled, e.handle_note AS handleNote, e.handle_status AS handleStatus, e.handle_by AS handleBy, DATE_FORMAT(e.handle_at, '%Y-%m-%d %H:%i') AS handleAt, e.handle_version AS handleVersion FROM fact_anomaly_event e LEFT JOIN dim_building b ON b.building_id = e.building_id
e.start_ts >= #{startDate} AND e.start_ts < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND e.anomaly_type = #{anomalyType} AND e.severity = #{severity} AND e.duration_hours >= #{minDuration} AND e.handle_status = #{handleStatus} AND e.site_id = #{siteId}
AND e.building_id IN #{b}
GROUP BY e.id ORDER BY e.start_ts DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM fact_anomaly_event e

    e.start_ts >= #{startDate} AND e.start_ts < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
    AND e.anomaly_type = #{anomalyType}
    AND e.severity = #{severity}
    AND e.duration_hours >= #{minDuration}
    AND e.handle_status = #{handleStatus}
    AND e.site_id = #{siteId}

        AND e.building_id IN
        #{b}

SELECT e.id AS anomalyId, e.building_id AS buildingId, DATE_FORMAT(e.start_ts, '%Y-%m-%d %H:%i') AS startTs, DATE_FORMAT(e.end_ts, '%Y-%m-%d %H:%i') AS endTs, e.duration_hours AS durationHours, e.anomaly_type AS anomalyType, e.severity, e.peak_value AS peakValue, e.baseline_value AS baselineValue, e.deviation_pct AS deviationPct, ROUND(COALESCE(e.deviation_pct, 0) * (1 + LN(e.duration_hours + 1)), 2) AS score FROM fact_anomaly_event e WHERE e.start_ts >= #{startDate} AND e.start_ts < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND e.building_id IN #{b}
ORDER BY score DESC LIMIT #{limit}

SELECT '异常时段' AS `group`, COUNT(*) AS hours, ROUND(AVG(electricity_kwh), 1) AS avgKwh, ROUND(AVG(air_temperature_c), 1) AS avgTemp, ROUND(AVG(humidity_pct), 1) AS avgHumidity, ROUND(AVG(occupancy_density), 2) AS avgOccupancy, ROUND(AVG(cop), 2) AS avgCop, ROUND(AVG(chw_supply_temp_c), 2) AS avgSupplyTemp, ROUND(AVG(chw_return_temp_c - chw_supply_temp_c), 2) AS avgDeltaT FROM fact_energy_hourly
anomaly_flag = 1 AND stat_year >= YEAR(#{startDate}) AND stat_year <= YEAR(#{endDate}) AND ts >= #{startDate} AND ts < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND building_id IN #{b}
UNION ALL SELECT '正常时段' AS `group`, COUNT(*) AS hours, ROUND(AVG(electricity_kwh), 1), ROUND(AVG(air_temperature_c), 1), ROUND(AVG(humidity_pct), 1), ROUND(AVG(occupancy_density), 2), ROUND(AVG(cop), 2), ROUND(AVG(chw_supply_temp_c), 2), ROUND(AVG(chw_return_temp_c - chw_supply_temp_c), 2) FROM fact_energy_hourly
anomaly_flag = 0 AND stat_year >= YEAR(#{startDate}) AND stat_year <= YEAR(#{endDate}) AND ts >= #{startDate} AND ts < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND building_id IN #{b}
